def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    cr = sum(r for r, c in pts) / len(pts)
    cc = sum(c for r, c in pts) / len(pts)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue

                d1 = (r - cr) ** 2 + (c - cc) ** 2
                d2 = (nr - cr) ** 2 + (nc - cc) ** 2
                if d1 >= d2:
                    sr, sc, step_r, step_c = r, c, -dr, -dc
                else:
                    sr, sc, step_r, step_c = nr, nc, dr, dc

                rr, col = sr + step_r, sc + step_c
                while 0 <= rr < h and 0 <= col < w:
                    if out[rr][col] == bg:
                        out[rr][col] = color
                    rr += step_r
                    col += step_c
    return out
